/**
 * Prebuild script: generate web/lib/generated/shared-prompts.ts from the
 * single-source prompt/schema files in core/.
 *
 * Source of truth:
 *   core/prompts/build_model.md
 *   core/schemas/model_schema.json
 *   core/schemas/context_schema.json
 *
 * The generated file is committed to git (same pattern as the data
 * snapshots): if the core/ sources are missing (e.g. a partial checkout),
 * the committed version is preserved.
 *
 * Run: node scripts/build-shared-prompts.mjs
 */

import { readFile, writeFile, mkdir } from "node:fs/promises";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const CORE_DIR = join(__dirname, "..", "..", "core");
const OUT_DIR = join(__dirname, "..", "lib", "generated");
const OUT_FILE = join(OUT_DIR, "shared-prompts.ts");

async function main() {
  let prompt, modelSchema, contextSchema;
  try {
    prompt = await readFile(join(CORE_DIR, "prompts", "build_model.md"), "utf-8");
    modelSchema = JSON.parse(
      await readFile(join(CORE_DIR, "schemas", "model_schema.json"), "utf-8"),
    );
    contextSchema = JSON.parse(
      await readFile(join(CORE_DIR, "schemas", "context_schema.json"), "utf-8"),
    );
  } catch (err) {
    console.warn(`[shared-prompts] core/ sources not found: ${err.message}`);
    console.warn(`[shared-prompts] Skipping; preserving committed ${OUT_FILE}`);
    return;
  }

  const banner =
    "// AUTO-GENERATED by scripts/build-shared-prompts.mjs — DO NOT EDIT.\n" +
    "// Source of truth: core/prompts/build_model.md, core/schemas/*.json\n\n";

  const body =
    `export const BUILD_MODEL_PROMPT = ${JSON.stringify(prompt)};\n\n` +
    `export const MODEL_SCHEMA = ${JSON.stringify(modelSchema, null, 2)};\n\n` +
    `export const CONTEXT_SCHEMA = ${JSON.stringify(contextSchema, null, 2)};\n`;

  await mkdir(OUT_DIR, { recursive: true });
  await writeFile(OUT_FILE, banner + body, "utf-8");
  console.log(`[shared-prompts] Generated ${OUT_FILE}`);
}

main().catch((err) => {
  console.error("[shared-prompts] Failed:", err);
  process.exit(1);
});
